package com.eidolon.sc.mobile;
import org.json.*;import java.time.*;import java.util.*;
/** Bounded history and clock repair. A plan never becomes evidence merely because time passed. */
final class LifeHistory {
 static final int MAX_ARCHIVES=12;
 static String canonical(Object v)throws Exception{
  if(v instanceof JSONObject){JSONObject o=(JSONObject)v;List<String> keys=new ArrayList<>();o.keys().forEachRemaining(keys::add);Collections.sort(keys);StringBuilder b=new StringBuilder("{");for(String k:keys)b.append(JSONObject.quote(k)).append(':').append(canonical(o.get(k))).append(',');return b.append('}').toString();}
  if(v instanceof JSONArray){StringBuilder b=new StringBuilder("[");JSONArray a=(JSONArray)v;for(int i=0;i<a.length();i++)b.append(canonical(a.get(i))).append(',');return b.append(']').toString();}return v instanceof String?JSONObject.quote((String)v):String.valueOf(v);
 }
 static String semanticKey(JSONObject s)throws Exception{JSONObject out=new JSONObject();for(String k:new String[]{"enabled","evolution","eventOnlyReach","zone","clockRollback","events","goals","profile","archives"})if(s.has(k))out.put(k,s.get(k));return canonical(out);}
 static void archive(JSONObject s,JSONObject goal,long now)throws Exception{
  String id=goal.getString("id");JSONArray old=s.getJSONArray("events"),evidence=new JSONArray(),events=new JSONArray(),goals=new JSONArray(),memories=new JSONArray();Set<String> removed=new HashSet<>();removed.add(id);
  boolean changed=true;while(changed){changed=false;for(int i=0;i<old.length();i++){JSONObject e=old.getJSONObject(i);if((id.equals(e.optString("goalId"))||removed.contains(e.optString("parent")))&&removed.add(e.getString("id")))changed=true;}}
  for(int i=0;i<old.length();i++){JSONObject e=old.getJSONObject(i);if(!removed.contains(e.getString("id")))events.put(e);else if(!e.optString("kind").equals("activity")){JSONObject r=new JSONObject();for(String k:new String[]{"id","title","kind","status","at","parent","source","messageRef"})r.put(k,e.opt(k));evidence.put(r);}}
  // At most one root, five steps and eight outstanding obstacles; retain explicit uncertainty.
  while(evidence.length()>14)evidence.remove(1);
  JSONObject root=LifeData.find(old,id);JSONObject item=new JSONObject().put("id",id).put("title",goal.getString("title")).put("status",goal.getString("status")).put("at",root==null?now:root.optLong("at")).put("archivedAt",now).put("progress",goal.getInt("progress")).put("stepsCount",goal.getJSONArray("steps").length()).put("interest",goal.optString("interest","practice")).put("source","archived_virtual_history").put("evidence",evidence);
  JSONArray archives=s.optJSONArray("archives");if(archives==null)archives=new JSONArray();archives.put(item);while(archives.length()>MAX_ARCHIVES)archives.remove(0);
  for(int i=0;i<s.getJSONArray("goals").length();i++){JSONObject g=s.getJSONArray("goals").getJSONObject(i);if(!id.equals(g.getString("id")))goals.put(g);}
  for(int i=0;i<s.getJSONArray("memories").length();i++){JSONObject m=s.getJSONArray("memories").getJSONObject(i);if(!removed.contains(m.getString("eventId")))memories.put(m);}
  s.put("archives",archives).put("events",events).put("goals",goals).put("memories",memories);
 }
 static JSONArray relevant(JSONObject s,String query,long now)throws Exception{
  JSONArray a=s.optJSONArray("archives"),out=new JSONArray();if(a==null||query.trim().isEmpty())return out;List<JSONObject> candidates=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject g=a.getJSONObject(i);if(!g.optBoolean("uncertain")&&g.optLong("at")<=now&&Recall.score(query,g.getString("title"))>0)candidates.add(g);}
  candidates.sort((x,y)->Double.compare(Recall.score(query,y.optString("title")),Recall.score(query,x.optString("title"))));for(int i=0;i<Math.min(2,candidates.size());i++){JSONObject g=candidates.get(i);out.put(new JSONObject().put("id",g.getString("id")).put("title",g.getString("title")).put("at",g.getLong("at")).put("status",g.getString("status")).put("progress",g.getInt("progress")).put("stepsCount",g.getInt("stepsCount")).put("source",g.getString("source")));}return out;
 }
 static void calibrate(JSONObject s,long now,ZoneId zone)throws Exception{
  JSONArray events=s.getJSONArray("events"),memories=new JSONArray();
  for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);if(e.optLong("at")>now&&!e.optString("status").equals("planned"))e.put("status","uncertain").put("source","clock_recalibration");if(e.optLong("resolvedAt")>now){e.put("status","open");e.remove("resolvedAt");e.remove("resolvedBy");}if(e.optLong("mentionedAt")>now){e.put("mentionedAt",0).put("messageRef","");}}
  JSONArray goals=s.getJSONArray("goals");for(int i=0;i<goals.length();i++){JSONObject g=goals.getJSONObject(i);int progress=0;long last=0;for(int j=0;j<g.getJSONArray("steps").length();j++){JSONObject step=LifeData.find(events,g.getString("id")+"/step/"+j);if(step==null||!step.optString("status").equals("completed")||step.optLong("at")>now)break;progress++;last=Math.max(last,step.optLong("at"));}g.put("progress",progress).put("lastDay",last==0?"":LifeData.day(last,zone));JSONObject root=LifeData.find(events,g.getString("id"));boolean cancelled=g.optString("status").equals("cancelled")&&root!=null&&root.optLong("at")<=now;g.put("status",cancelled?"cancelled":progress==g.getJSONArray("steps").length()?"completed":"active");if(root!=null&&!cancelled){if(root.optLong("start")>now)g.put("status","cancelled");else root.put("status",g.getString("status").equals("completed")?"completed":"open").put("at",last>0?last:root.getLong("start"));}}
  // If several historical goals reopen, keep one actionable goal; the rest stay cancelled/uncertain.
  boolean active=false;for(int i=goals.length()-1;i>=0;i--){JSONObject g=goals.getJSONObject(i);if(g.optString("status").equals("active")){if(active){g.put("status","cancelled");JSONObject root=LifeData.find(events,g.getString("id"));if(root!=null)root.put("status","uncertain");}active=true;}}
  JSONArray archives=s.optJSONArray("archives");if(archives!=null)for(int i=0;i<archives.length();i++){JSONObject a=archives.getJSONObject(i);boolean uncertain=a.optLong("at")>now;JSONArray evidence=a.getJSONArray("evidence");for(int j=0;j<evidence.length();j++)if(evidence.getJSONObject(j).optLong("at")>now)uncertain=true;a.put("uncertain",uncertain);}
  JSONObject p=s.getJSONObject("profile"),base=s.optJSONObject("profileBase");boolean validBase=base!=null&&base.optLong("at")<=now;double confidence=validBase?base.getDouble("confidence"):50;JSONObject interests=validBase?new JSONObject(base.getJSONObject("interests").toString()):new JSONObject();JSONArray log=s.getJSONArray("evolutionLog"),kept=new JSONArray();String lastDay="";
  for(int i=0;i<log.length();i++){JSONObject row=log.getJSONObject(i),e=LifeData.find(events,row.optString("eventId"));if(row.optLong("at")>now)continue;boolean evidence=e!=null&&e.optString("status").equals("completed")&&e.optLong("at")<=now;String tag=row.optString("interest","");if(!evidence&&archives!=null)for(int j=0;j<archives.length();j++){JSONObject a=archives.getJSONObject(j);JSONObject ae=LifeData.find(a.getJSONArray("evidence"),row.optString("eventId"));if(!a.optBoolean("uncertain")&&ae!=null&&ae.optString("status").equals("completed")){evidence=true;if(tag.isEmpty())tag=a.optString("interest");}}if(!evidence)continue;if(tag.isEmpty()&&e!=null){JSONObject g=LifeData.find(goals,e.optString("parent"));if(g!=null)tag=g.optString("interest");}tag=LifeData.interest(tag);double before=confidence;confidence=Math.min(80,confidence+.5);interests.put(tag,Math.min(20,interests.optInt(tag)+1));row.put("before",before).put("after",confidence).put("interest",tag);kept.put(row);lastDay=LifeData.day(row.getLong("at"),zone);}
  p.put("confidence",confidence).put("interests",interests).put("lastEvolutionDay",lastDay);s.put("evolutionLog",kept);if(!validBase)s.remove("profileBase");
  JSONArray prior=s.getJSONArray("memories");for(int i=0;i<prior.length();i++){JSONObject m=prior.getJSONObject(i),e=LifeData.find(events,m.optString("eventId"));if(e==null)continue;m.put("at",e.optLong("at")).put("status",e.getString("status")).put("confirmed",!e.optString("status").equals("uncertain")).put("source",e.optString("source"));memories.put(m);}s.put("memories",memories);
  // Interaction effects cannot be reconstructed safely from a future-dated aggregate.
  s.put("influences",new JSONArray()).put("actual",JSONObject.NULL).put("awakeUntil",0).put("observedAt",now).put("clockRollback",false);s.remove("lastBehavior");s.getJSONObject("emotion").put("valence",0.0).put("energy",70.0).put("at",now).put("label","平静").put("source","clock_recalibration");
 }
 static void validate(JSONObject s)throws Exception{
  JSONArray a=s.optJSONArray("archives");if(a==null)a=new JSONArray();if(a.length()>MAX_ARCHIVES)throw new Exception("生活归档过多");Set<String> ids=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject g=a.getJSONObject(i);if(!ids.add(LifeData.shortText(g.getString("id"),180))||LifeData.find(s.getJSONArray("events"),g.getString("id"))!=null)throw new Exception("归档引用重复");LifeData.shortText(g.getString("title"),100);if(!Arrays.asList("completed","cancelled").contains(g.getString("status"))||!g.getString("source").equals("archived_virtual_history")||g.getLong("at")<0||g.getLong("archivedAt")<0||g.getInt("progress")<0||g.getInt("progress")>g.getInt("stepsCount")||g.getInt("stepsCount")<2||g.getInt("stepsCount")>5)throw new Exception("归档状态无效");JSONArray evidence=g.getJSONArray("evidence");if(evidence.length()>14)throw new Exception("归档证据过多");Set<String> seen=new HashSet<>();for(int j=0;j<evidence.length();j++){JSONObject e=evidence.getJSONObject(j);if(!seen.add(LifeData.shortText(e.getString("id"),180)))throw new Exception("归档证据重复");LifeData.shortText(e.getString("title"),160);if(e.getLong("at")<0||e.optString("messageRef").length()>200)throw new Exception("归档来源无效");}}
  JSONObject base=s.optJSONObject("profileBase");if(base!=null){double c=base.getDouble("confidence");if(base.getLong("at")<0||base.getLong("at")>253402300799999L||!Double.isFinite(c)||c<0||c>80||base.getJSONObject("interests").length()>5)throw new Exception("人格检查点无效");JSONObject bi=base.getJSONObject("interests");for(Iterator<String> it=bi.keys();it.hasNext();){String k=it.next();if(!LifeData.interest(k).equals(k)||bi.getInt(k)<0||bi.getInt(k)>20)throw new Exception("人格兴趣检查点无效");}}
 }
 private LifeHistory(){}
}
